['Grace', q{Without making my sponsor lose face.}, q{不让 sponsor 丢面子。}, q{Panels listen for whether you win while keeping others intact — say it explicitly.}],
['Follow-up', q{I would write the memo sooner.}, q{我会更早写出备忘录。}, q{A specific self-criticism with a mechanism beats "nothing, it went great".}],
['Test', q{Would I be comfortable if everyone read the transcript?}, q{所有人看到完整记录我会不会不安？}, q{A portable ethics test — quoting your own heuristic reads as maturity.}],
['Landing', q{Being right is table stakes; being trusted is the job.}, q{正确只是入场券，被信任才是工作本身。}, q{The one-line lesson that ends a failure story with growth, not wounds.}],
],
vocab => [
